server.registerTool(
    'brief',
    {
      description:
        'START HERE for any question about this codebase - ask it before reading files, since a grounded hit usually removes the need to. Returns code hits, doc-section instructions, and trusted memories as SEPARATE typed groups (code and memory scores are never fused). Every hit carries a one-line snippet plus grounding: semantic means authored purpose is in llm (and if inherited is set, that purpose describes the owning file/cluster named in via, NOT the symbol itself); code means nothing has been authored and the snippet is all there is. coverage gives the grounded fraction of the response - a low ratio is the signal to fall back to reading source. cursor pages the code offset; maxTokens (default 2000) trims the payload; ifHash collapses a repeat to ~30 bytes.',
      inputSchema: {
        q: z.string(),
        paths: z.array(z.string()).optional(),
        targetIds: z.array(z.string()).optional(),
        sources: z.array(z.enum(['team', 'local', 'global'])).optional(),
        maxTokens: z.number().int().positive().optional(),
        cursor: z.string().optional(),
        ifHash: z.string().optional(),
      },
    },
    async (a) => TOOL_RESULT(verbs.brief(a)),
  );

